<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api } from '@/lib/api'; import type { Booking } from '@/types'; import { useBookingStore } from '@/stores/booking'
const store=useBookingStore(); const bookings=ref<Booking[]>([]); const error=ref(''); const money=(v:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(v); const formatSlot=(value:string)=>new Date(value).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})
onMounted(async()=>{ try { const result=await api.get<{data:Booking[]}>('/bookings'); bookings.value=result.data } catch(e:any){error.value=e.message||'Không tải được booking.'} })
async function cancel(booking:Booking){ if(!confirm('Bạn chắc chắn muốn hủy booking này?'))return; try { await api.post(`/bookings/${booking.code}/cancel`,{reason:'Khách tự hủy'}); booking.status=booking.status==='confirmed'?'refund_pending':'cancelled' } catch(e:any){error.value=e.message||'Không thể hủy booking.'} }
</script>
<template><section class="row"><div><div class="eyebrow">Your activity</div><h1 class="page-title">My bookings</h1><p class="muted">Theo dõi thanh toán và lịch sân đã đặt.</p></div><RouterLink to="/courts" class="btn">Đặt sân mới</RouterLink></section><p v-if="error" class="error">{{error}}</p><div v-if="!bookings.length" class="card" style="margin-top:28px"><p>Chưa có booking nào.</p></div><div v-for="booking in bookings" :key="booking.id" class="card" style="margin-top:14px"><div class="row"><div><h3>{{booking.court.name}} · {{booking.code}}</h3><p class="muted">{{booking.slots.map(s=>formatSlot(s.starts_at)).join(' · ')}}</p></div><span class="badge">{{booking.status}}</span></div><div class="row"><strong>{{money(booking.total_amount)}}</strong><button v-if="['pending_payment','confirmed'].includes(booking.status)" class="btn" @click="cancel(booking)">Hủy booking</button></div></div></template>
